/** Draws [icon] at [size], tinted [tint] (defaults to the theme icon colour). */
@Composable
fun TakuIcon(icon: TakuIcons, size: Dp, modifier: Modifier = Modifier, tint: Color = TakuTheme.colors.icon) {
  Canvas(modifier.size(size)) {
    val s = this.size.width / icon.viewport
    scale(s, s, pivot = Offset.Zero) {
      if (icon.stroke > 0f) drawPath(icon.path, tint, style = Stroke(icon.stroke, cap = StrokeCap.Round, join = StrokeJoin.Round))
      else drawPath(icon.path, tint)
    }
  }
}
